jQuery(function(a){a("a#clear_cache").bind("click",function(){var c=a(this);if(!c.data("oldhtml")){c.data("oldhtml",c.html())}if(c.html()=="Clearing..."){return false}c.html("Clearing...");var b=c.data("type");a.post(ajaxurl,{tr_action:"clear_cache",action:"clear_cache",type:b},function(d){c.html(c.data("oldhtml"));if(b=="html"){a(".count_cache").html("0")}else{if(b=="js"){a(".count_cache_js").html("0")}else{if(b=="css"){a(".count_cache_css").html("0")}}}});return false})});